const site=document.body.dataset.site||'clinic'
const route=()=>{try{if(!location.hash)return{brand:site,page:'home',id:'',params:new URLSearchParams(),invalid:false};const raw=location.hash.replace(/^#\/?/,''),[path,query='']=raw.split('?'),parts=path?path.split('/').map(decodeURIComponent):[site],brand=parts[0]||site,page=parts[1]||'home',id=parts[2]||'';return{brand,page,id,params:new URLSearchParams(query),invalid:parts.length>3}}catch{return{brand:site,page:'not-found',id:'',params:new URLSearchParams(),invalid:true}}}
function validRoute(r){
 if(r.invalid)return false;
 if(r.brand==='hub')return r.page==='home'&&!r.id;
 const pages={clinic:['home','about','services','doctors','packages','articles','contact','appointment'],eco:['home','story','portfolio','stores','partners','journal','events','contact'],shop:['home','products','about','articles','favorites','cart','checkout','order','contact']};
 if(!pages[r.brand]?.includes(r.page))return false;
 if(!r.id)return true;
 const details={clinic:{services:centers,doctors,packages,articles},eco:{journal:ecoStories()},shop:{products,articles:shopStories(locale,photos)}};
 return !!details[r.brand]?.[r.page]?.some(item=>item.id===r.id);
}
function missingPage(r){const brand=['clinic','eco','shop'].includes(r.brand)?r.brand:site,back=brand==='clinic'&&['doctors','services','packages','articles'].includes(r.page)?brand+'/'+r.page:brand==='shop'&&['products','articles'].includes(r.page)?brand+'/'+r.page:brand==='eco'&&r.page==='journal'?'eco/journal':brand==='hub'?'':brand;return `${header(brand,'not-found')}<main><section class="empty-state missing-page"><span class="kicker">PAGE NOT FOUND · 404</span><h1>${T('ไม่พบหน้าที่คุณกำลังค้นหา','We couldn’t find this page')}</h1><p>${T('ลิงก์นี้อาจไม่ถูกต้องหรือเนื้อหาไม่มีอยู่ในต้นแบบ ลองกลับไปเลือกจากรายการอีกครั้ง','This link may be incorrect or the content is not available in this prototype. Return to the collection to continue.')}</p><a class="primary-button blue-button" href="#/${back}">${T('กลับไปเลือกดูอีกครั้ง','Back to browsing')} →</a><a class="outline-link" href="#/${brand==='hub'?'':brand}">${T('กลับหน้าหลัก','Home')}</a></section></main>${footer(brand==='hub'?'dlg':brand)}`}
function goto(to){const target='/'+to.replace(/^\//,'');if(location.hash==='#'+target)render();else location.hash=target}
function navLink(label,to,active){return `<a class="${active?'active':''}" href="#/${to}">${label}</a>`}
