 if(brand==='clinic')return `<div class="clinic-top"><div class="top-inner"><span>โรงพยาบาลลูม่า · LUMA HEALTHCARE</span><span>สายด่วน 02 555 0188 &nbsp; | &nbsp; เปิดทุกวัน 08:00–20:00</span></div></div><header class="clinic-header"><a class="clinic-logo" href="#/clinic"><i>✚</i><span>LUMA<small>WELLNESS CLINIC</small></span></a><nav>${navLink(T('หน้าแรก','Home'),'clinic',page==='home')}${navLink(T('เกี่ยวกับเรา','About us'),'clinic/about',page==='about')}${navLink(T('ศูนย์บริการ','Medical centers'),'clinic/services',page==='services')}${navLink(T('แพทย์','Doctors'),'clinic/doctors',page==='doctors')}${navLink(T('แพ็กเกจ','Packages'),'clinic/packages',page==='packages')}${navLink(T('บทความ','Journal'),'clinic/articles',page==='articles')}${navLink(T('ติดต่อ','Contact'),'clinic/contact',page==='contact')}<a class="clinic-menu-book" href="#/clinic/appointment">${T('นัดหมายแพทย์','Book a visit')} →</a></nav><div class="header-right">${languageSwitch()}<a class="clinic-book" href="#/clinic/appointment">${T('นัดหมายแพทย์','Book a visit')}</a><button class="mobile-menu" data-mobile-menu aria-expanded="false" aria-label="Menu">☰</button></div></header>`
