 if(brand==='shop')return `<div class="shop-promo">${T('ส่งฟรีเมื่อซื้อครบ ฿1,500 · รับส่วนลด 10% สำหรับสมาชิกใหม่','Free delivery on orders over ฿1,500 · Save 10% on your first order')} <a href="#/shop/products">${T('เลือกซื้อเลย','Shop now')}</a></div><header class="shop-header"><a class="shop-logo" href="#/shop"><i>n.</i><span>NOURISH<small>WELLNESS MARKET</small></span></a><nav>${navLink(T('หน้าหลัก','Home'),'shop',page==='home')}${navLink(T('สินค้าทั้งหมด','Shop all'),'shop/products',page==='products')}${navLink(T('อาหารเสริม','Supplements'),'shop/products?cat=supplements',false)}${navLink(T('ดูแลผิว','Body care'),'shop/products?cat=care',false)}${navLink(T('เรื่องราวของเรา','Our story'),'shop/about',page==='about')}</nav><div class="shop-actions"><button class="search-toggle" data-search-toggle aria-label="Search">⌕</button>${languageSwitch()}<a href="#/shop/favorites" class="cart-link" aria-label="Favorites">♡ <span>${favorites.size}</span></a><a href="#/shop/cart" class="cart-link" aria-label="${T('ตะกร้าสินค้า','Shopping basket')}">${basketIcon}<span>${cart.reduce((s,x)=>s+x.qty,0)}</span></a><button class="mobile-menu" data-mobile-menu aria-expanded="false" aria-label="Menu">☰</button></div></header>`
 return `<header class="hub-header"><a class="hub-logo" href="#/"><i>DLG</i> Digital Light Group <span>/ demo website</span></a><div>${T('ต้นแบบเว็บไซต์ธุรกิจสุขภาพและสุขภาวะ','HEALTH & WELLNESS DIGITAL SHOWCASE')}</div>${languageSwitch()}</header>`
