const footer=(brand='clinic')=>`<footer class="site-footer ${brand}-footer"><a href="#/${brand==='clinic'?'clinic':brand==='eco'?'eco':brand==='shop'?'shop':''}" class="footer-mark">${brand==='dlg'?'DLG · DIGITAL LIGHT GROUP DEMO WEBSITE':brand==='clinic'?'✚ LUMA WELLNESS CLINIC':brand==='eco'?'✿ goodkind':'n. NOURISH MARKET'}</a><span>${T('ดูแลด้วยความใส่ใจ ทุกวัน','Thoughtful care, every day')}</span><a href="#/${brand==='dlg'?'eco':brand}/contact">${T('ติดต่อเรา','Contact us')}</a><small>© 2026 · ${brand==='dlg'?'DIGITAL LIGHT GROUP':'DEMO WEBSITE PROTOTYPE'}</small></footer>`
function hub(){return `${header()}<main><section class="hub-hero"><div class="hub-hero-copy"><div class="hub-kicker">${T('ต้นแบบเว็บไซต์ธุรกิจ','HEALTH & WELLNESS PROTOTYPES')}</div><h1>${T('สุขภาพที่ดี เริ่มจากประสบการณ์ที่ดี','Better wellbeing starts with a better digital experience.')}</h1><p>${T('สามแนวทางเว็บไซต์ เพื่อเชื่อมผู้คนเข้ากับบริการ สินค้า และเรื่องราวด้านสุขภาพ','Three digital directions connecting people with better care, products and everyday wellness.')}</p><a href="#journey" class="hub-button">${T('ดูเส้นทางลูกค้า','Explore the customer journey')} ↓</a></div><div class="hub-hero-photo"><img src="${photos.family}" alt="ครอบครัวใช้เวลาในสวน"><div class="hero-photo-caption">CARE THAT FITS REAL LIFE <span>DIGITAL LIGHT GROUP  /  2026</span></div></div></section><section class="showcase-intro"><div class="kicker">THREE DIGITAL DIRECTIONS</div><h2>${T('เลือกชมเว็บไซต์ต้นแบบ','Explore the prototypes')}</h2><p>${T('แต่ละเว็บไซต์ออกแบบตามบริบทของธุรกิจและเส้นทางการตัดสินใจของลูกค้า','Each experience is tailored to its business model and customer journey.')}</p></section><section class="prototype-grid">${[["clinic",T('โรงพยาบาลและคลินิก','Hospital & wellness clinic'),T('ความเชี่ยวชาญและความไว้วางใจ','Expertise, trust and care'),photos.clinic,'#/clinic'],['eco',T('Wellness ecosystem','Wellness ecosystem'),T('เชื่อมสินค้า บริการ และพาร์ตเนอร์','Products, services and partners'),photos.wellness,'#/eco'],['shop',T('ร้านสินค้าเพื่อสุขภาพ','Health & wellness e-commerce'),T('ค้นพบสินค้า เลือกซื้อ และกลับมาอีกครั้ง','Discover, shop and return'),photos.store,'#/shop']].map((p,i)=>`<a class="prototype-card card-${p[0]}" href="${p[4]}"><img src="${p[3]}" alt=""><div class="prototype-count">0${i+1} / ${['CORPORATE','ECOSYSTEM','E-COMMERCE'][i]}</div><div class="prototype-info"><h3>${p[1]}</h3><p class="prototype-purpose">${p[2]}</p><div class="prototype-sales"><small>${T('เหมาะสำหรับ','BUSINESS FIT')}</small><p>${[T('โรงพยาบาล คลินิก และศูนย์ตรวจสุขภาพที่ต้องการรับคำขอนัดหมาย','Hospitals, clinics and screening centers that need appointment inquiries.'),T('เครือแบรนด์สุขภาวะ ธุรกิจค้าปลีก และผู้ให้บริการที่ต้องการเชื่อมสาขาและพันธมิตร','Wellness brand groups, retailers and service businesses connecting locations and partners.'),T('แบรนด์อาหารเสริม สกินแคร์ และอุปกรณ์สุขภาพที่ต้องการขายสินค้าออนไลน์','Supplement, skincare and health device brands selling online.')][i]}</p><ul>${[ [T('ค้นหาแพทย์และดูตารางตรวจ','Doctor search & schedules'),T('เลือกแพ็กเกจและส่งคำขอนัดหมาย','Packages & appointment requests')], [T('ค้นหาสาขาและดูแผนที่','Store search & interactive maps'),T('สอบถามธุรกิจและลงทะเบียนกิจกรรม','Partner inquiries & event registration')], [T('ค้นหา กรอง และเปรียบเทียบสินค้า','Product search, filters & comparison'),T('รายการโปรด ตะกร้า และ Checkout จำลอง','Favorites, basket & demo checkout')] ][i].map(feature=>`<li>✓ ${feature}</li>`).join('')}</ul></div><span class="prototype-open">${T('เปิดดูต้นแบบ','Explore prototype')}</span></div></a>`).join('')}</section><section id="journey" class="journey-wrap"><div class="journey-heading"><div><div class="kicker">CUSTOMER JOURNEY</div></div></div><div class="journey-table"><div class="journey-head"><span>STAGE</span><span>${T('พฤติกรรมผู้ใช้','CUSTOMER NEED')}</span><span>TOUCHPOINT / FEATURE</span><span>${T('เป้าหมายของระบบ','SYSTEM GOAL')}</span></div>${[[T('1. รับรู้','1. Awareness'),T('ค้นหาข้อมูลสุขภาพ หรือเห็นโฆษณา','Discover care through search or social'),T('Google Search / Social Ads → Landing Page','Search · social · landing page'),T('เข้าถึงข้อมูลได้เร็วและสร้างความไว้วางใจ','Build trust and make key information easy to find'),'clinic'],[T('2. พิจารณา','2. Consideration'),T('อ่านข้อมูลบริการ ตรวจสอบความเชี่ยวชาญ','Review services and expertise'),T('Service Detail · Doctor Profile · Standards','Service details · profiles · standards'),T('สร้างความมั่นใจในการเลือกบริการ','Build confidence'),'clinic'],[T('3. เปรียบเทียบ','3. Evaluation'),T('เปรียบเทียบแพ็กเกจและตรวจสอบสถานที่','Compare packages and locations'),T('Packages · Promotions · Location','Prices · offers · directions'),T('ให้ข้อมูลครบและลดความยุ่งยาก','Make comparison easy'),'clinic'],[T('4. ตัดสินใจ','4. Action'),T('ตัดสินใจนัดหมายหรือสั่งซื้อ','Book an appointment or place an order'),T('Appointment Form · Online Cart · Call CTA','Booking · checkout · call to action'),T('เปลี่ยนความสนใจเป็นคำขอหรือนัดหมาย','Turn interest into action'),'shop'],[T('5. หลังใช้บริการ','5. Post-Service'),T('ติดตามผล อ่านบทความและแลกเปลี่ยน','Stay informed and connected'),T('Articles · Health Newsletter · Events','Journal · newsletter · community events'),T('สร้างการกลับมาใช้บริการซ้ำ','Encourage return visits') ,'eco']].map((r,i)=>`<div class="journey-row"><b>${r[0]}</b><span>${r[1]}</span><span>${r[2]}</span><span>${r[3]}</span></div>`).join('')}</div></section></main>${footer('dlg')}`}

function clinicHome(){return `<section class="clinic-hero"><img class="clinic-cover" src="${photos.clinic}" alt="คลินิกสุขภาพในบรรยากาศสงบ"><div class="clinic-hero-shade"></div><div class="clinic-hero-content"><div class="clinic-crumb">HOME &nbsp; › &nbsp; LUMA WELLNESS</div><span class="kicker light-kicker">PREVENTION · PERSONALIZED CARE · WELLNESS</span><h1>${T('ลูม่า เวลเนส คลินิก','Luma Wellness Clinic')}</h1><p>${T('เข้าใจสุขภาพของคุณให้ลึกขึ้น เพื่อใช้ชีวิตได้ดีขึ้นในทุกวัน','Personalized preventive care, specialist expertise and a calmer clinic experience — shaped around you.')}</p><a class="primary-button" href="#/clinic/services">${T('สำรวจศูนย์บริการ','Explore our services')} <b>→</b></a></div><div class="hero-control">01 <i></i> 03 <span>SCROLL TO EXPLORE ↓</span></div></section><div class="clinic-quick"><span class="quick-emblem">✚</span><b>${T('พร้อมเริ่มดูแลสุขภาพของคุณหรือยัง?','Ready to take the next step in your health?')}</b><small>${T('ทีมดูแลผู้ป่วยพร้อมช่วยแนะนำ','Our care team is here to help.')}</small><a href="#/clinic/appointment">${T('นัดหมายแพทย์','Book an appointment')} <span></span></a><a href="tel:+6625550188" class="quick-phone">☎ 02 555 0188</a></div><section class="clinic-section"><div class="section-lead"><div><span class="kicker">OUR SERVICES</span><h2>${T('ดูแลสุขภาพเชิงป้องกัน','Prevention and wellness, together')}</h2><p>${T('ศูนย์บริการเฉพาะทาง เชื่อมทีมแพทย์เข้ากับแผนการดูแลที่เหมาะกับคุณ','Specialist centers and thoughtful care plans shaped around your needs.')}</p></div><a class="outline-link" href="#/clinic/services">${T('ดูศูนย์บริการทั้งหมด','All medical centers')}</a></div><div class="clinic-centers">${centers.map(c=>`<a class="center-card" href="#/clinic/services/${c.id}"><img src="${c.pic}" alt=""><div><small>${locale==='th'?c.cat:c.enCat}</small><h3>${locale==='th'?c.name:c.en}</h3><span>${T('ดูรายละเอียด','View center')} →</span></div></a>`).join('')}</div></section><section class="featured-doctors"><div class="section-lead"><div><span class="kicker">OUR DOCTORS</span><h2>${T('ทีมแพทย์ที่พร้อมรับฟัง','Meet your care team')}</h2><p>${T('ผู้เชี่ยวชาญหลากหลายสาขา พร้อมดูแลในแบบของคุณ','Experienced specialists, ready to listen and guide.')}</p></div><a class="outline-link" href="#/clinic/doctors">${T('ค้นหาแพทย์','Find a doctor')}</a></div><div class="doctor-row">${doctors.map((d,i)=>`<article class="doctor-teaser"><a href="#/clinic/doctors/${d.id}"><img src="${d.image}" alt="${locale==='th'?d.name:d.en}"><div class="doctor-teaser-name"><small>${locale==='th'?d.specialty:d.enSpecialty}</small><h3>${locale==='th'?d.name:d.en}</h3><span>${T('ดูประวัติและตารางตรวจ','Profile & schedule')}</span></div></a></article>`).join('')}</div></section><section class="program-strip"><div><span class="kicker">HEALTH PROGRAMS</span><h2>${T('โปรแกรมสุขภาพที่ออกแบบให้คุณ','Health programs for your next chapter')}</h2></div><div class="program-pills">${packages.map(p=>`<a href="#/clinic/packages/${p.id}"><b>${locale==='th'?p.name:p.en}</b><small>${T('เริ่มต้น','From')} ฿${p.price.toLocaleString()}</small><span></span></a>`).join('')}</div><a class="program-more" href="#/clinic/packages">${T('ดูแพ็กเกจทั้งหมด','All programs')} →</a></section><section class="trust-band"><div class="trust-photo"><img src="${photos.team}" alt="ทีมดูแลสุขภาพ"></div><div class="trust-content"><span class="kicker">CARE YOU CAN TRUST</span><h2>${T('ความเชี่ยวชาญที่เข้าใจคุณ','Expert care, grounded in trust')}</h2><p>${T('มาตรฐานการดูแลที่ชัดเจน ทีมสหสาขาวิชาชีพ และบรรยากาศที่ใส่ใจในทุกรายละเอียด','Clear clinical standards, multidisciplinary care and a welcoming experience in every detail.')}</p><div class="trust-badges"><span><b>JCI</b><small>CARE STANDARDS</small></span><span><b>20+</b><small>YEARS OF CARE</small></span><span><b>4.9/5</b><small>PATIENT RATING</small></span></div></div></section><section class="clinic-atmosphere"><div class="section-lead"><div><span class="kicker">A LOOK INSIDE LUMA</span><h2>${T('บรรยากาศและพื้นที่บริการ','Spaces designed around care')}</h2><p>${T('ภาพตัวอย่างเพื่อแสดงแนวทางบรรยากาศของสถานพยาบาล','Sample stock photography showing the intended clinic atmosphere.')}</p></div></div><div class="clinic-atmosphere-grid"><figure><img src="${photos.clinic}" alt="${T('พื้นที่ต้อนรับและทางเดิน','Reception and clinic corridors')}"><figcaption>${T('พื้นที่ต้อนรับ','Welcoming spaces')}</figcaption></figure><figure><img src="${photos.team}" alt="${T('ทีมแพทย์และผู้เชี่ยวชาญ','Doctors and specialists')}"><figcaption>${T('ทีมดูแลผู้เชี่ยวชาญ','Specialist care team')}</figcaption></figure><figure><img src="${photos.wellness}" alt="${T('พื้นที่ส่งเสริมสุขภาวะ','Wellness and consultation space')}"><figcaption>${T('การดูแลสุขภาวะแบบองค์รวม','Whole-person wellbeing')}</figcaption></figure></div></section><section class="clinic-journal"><div class="section-lead"><div><span class="kicker">HEALTH LIBRARY</span><h2>${T('รู้จักสุขภาพของคุณมากขึ้น','A little more health knowledge')}</h2></div><a class="outline-link" href="#/clinic/articles">${T('อ่านบทความทั้งหมด','All articles')}</a></div><div class="article-teasers">${articles.map(a=>`<a class="article-teaser" href="#/clinic/articles/${a.id}"><img src="${a.image}" alt=""><small>${locale==='th'?a.cat:a.enCat}</small><h3>${locale==='th'?a.title:a.enTitle}</h3><span>${T('อ่านต่อ','Read article')} →</span></a>`).join('')}</div></section><section class="newsletter-strip clinic-newsletter"><div><span class="kicker">LUMA HEALTH NOTES</span><h2>${T('รับข่าวสารสุขภาพจากทีมลูม่า','Health notes from the Luma care team')}</h2><p>${T('รับบทความและข้อมูลการดูแลสุขภาพเป็นครั้งคราว','Occasional health articles and clinic updates by email.')}</p></div><form data-form="clinic-newsletter"><label class="sr-only" for="clinic-newsletter-email">Email</label><input id="clinic-newsletter-email" type="email" name="email" required placeholder="Email address"><button>${T('สมัครรับข่าวสาร','Subscribe')}</button><small class="form-message"></small><small class="prototype-note">${T('แบบฟอร์มตัวอย่าง · ยังไม่มีการบันทึกหรือส่งอีเมลจริง','Demo form · no data is stored and no email is sent.')}</small></form></section><div class="clinic-location-banner"><img src="${photos.clinic}" alt=""><div><span class="kicker light-kicker">COME VISIT US</span><h2>${T('สถานที่ที่ให้คุณเริ่มต้นดูแลตัวเอง','A welcoming place to begin')}</h2><a class="primary-button" href="#/clinic/contact">${T('สาขาและเส้นทาง','Locations & directions')}</a></div></div>`}
function clinicPage(page,id){let content='';const cTitle=T('ลูม่า เวลเนส คลินิก','Luma Wellness Clinic');
 if(page==='home')content=clinicHome();
 else if(page==='about')content=`<section class="page-banner"><img src="${photos.team}"><div><span class="kicker light-kicker">ABOUT LUMA</span><h1>${T('สุขภาวะดี เริ่มจากความเข้าใจ','Wellbeing starts with understanding.')}</h1><p>${T('เราผสานมาตรฐานการแพทย์เข้ากับการดูแลที่มองเห็นตัวตนและเป้าหมายของคุณ','We combine rigorous medical standards with care that sees the person behind every health goal.')}</p></div></section><section class="editorial-content"><span class="kicker">VISION & MISSION</span><h2>${T('วิสัยทัศน์ของเรา คือสุขภาพที่ดีในแบบของแต่ละคน','Our vision is a healthier life, defined by you.')}</h2><p>${T('ภารกิจของเราคือช่วยให้ผู้คนเข้าใจสุขภาพของตนเองก่อนเกิดปัญหา และเข้าถึงคำแนะนำที่ชัดเจนจากทีมผู้เชี่ยวชาญ','Our mission is to help people understand their health early and access clear guidance from an experienced care team.')}</p><div class="accreditations"><b>JCI</b><span>${T('มาตรฐานการดูแลผู้ป่วย','Patient care standards')}</span><b>HA</b><span>${T('พัฒนาคุณภาพบริการอย่างต่อเนื่อง','Continuous quality improvement')}</span><b>ISO</b><span>${T('ระบบบริหารจัดการคุณภาพ','Quality management systems')}</span></div><h2>${T('พื้นที่ผ่อนคลาย พร้อมสำหรับการดูแล','A calm setting, designed around care')}</h2><img class="editorial-photo" src="${photos.clinic}" alt="คลินิกในบรรยากาศผ่อนคลาย"><a class="primary-button blue-button" href="#/clinic/services">${T('รู้จักศูนย์บริการ','Explore our centers')}</a></section>`;
 else if(page==='services'&&!id)content=`<section class="page-banner"><img src="${photos.team}"><div><span class="kicker light-kicker">CENTERS & SERVICES</span><h1>${T('ศูนย์บริการเฉพาะทาง','Specialist centers, connected care.')}</h1><p>${T('บริการด้านสุขภาพเชิงป้องกันและดูแลเฉพาะทาง ครอบคลุมทุกช่วงชีวิต','Preventive and specialist services designed around every stage of life.')}</p></div></section><section class="listing-section"><div class="listing-toolbar"><span>${T('ศูนย์บริการ 4 แห่ง','4 medical centers')}</span><select><option>${T('ทุกความเชี่ยวชาญ','All specialties')}</option>${centers.map(c=>`<option>${locale==='th'?c.cat:c.enCat}</option>`).join('')}</select></div><div class="center-listing">${centers.map(c=>`<a href="#/clinic/services/${c.id}" class="center-list-card"><img src="${c.pic}"><div><small>${locale==='th'?c.cat:c.enCat}</small><h2>${locale==='th'?c.name:c.en}</h2><p>${c.desc}</p><b>${T('รายละเอียดและทีมแพทย์','Details & care team')} →</b></div></a>`).join('')}</div></section>`;
 else if(page==='services'&&id){let c=centers.find(x=>x.id===id)||centers[0];content=`<section class="detail-hero"><img src="${c.pic}"><div><div class="breadcrumb"><a href="#/clinic">${T('หน้าแรก','Home')}</a> › <a href="#/clinic/services">${T('ศูนย์บริการ','Centers')}</a></div><span class="kicker light-kicker">${locale==='th'?c.cat:c.enCat}</span><h1>${locale==='th'?c.name:c.en}</h1><p>${c.desc}</p><a class="primary-button" href="#/clinic/appointment?center=${c.id}">${T('นัดหมายรับคำปรึกษา','Book a consultation')}</a></div></section><section class="editorial-content"><span class="kicker">OUR APPROACH</span><h2>${T('เริ่มต้นจากการรับฟัง ออกแบบการดูแลร่วมกัน','Care that begins with listening')}</h2>${centerStory(c.id,locale)}<h2>${T('ทีมแพทย์ผู้เชี่ยวชาญ','Meet our specialists')}</h2><div class="doctor-row">${doctors.filter((_,i)=>id==='heart'?i===1:id==='brain'?i===2:true).map(d=>doctorCard(d)).join('')}</div><h2>${T('แพ็กเกจที่เกี่ยวข้อง','Related packages')}</h2><div class="related-packages">${packages.filter(p=>p.center===id).map(p=>`<a href="#/clinic/packages/${p.id}">${locale==='th'?p.name:p.en} <b>฿${p.price.toLocaleString()}</b></a>`).join('')}</div></section>`;}
 else if(page==='doctors'&&!id)content=`<section class="page-heading clinic-filter-heading"><span class="kicker">DOCTORS & SPECIALISTS</span><h1>${T('ค้นหาแพทย์และผู้เชี่ยวชาญ','Find a doctor')}</h1><p>${T('ค้นหาตามชื่อหรือสาขาความเชี่ยวชาญ','Search by name or area of expertise')}</p>${clinicDoctorSearch()}</section><section class="listing-section"><p class="clinic-result-count" id="doctor-results-count" role="status" aria-live="polite"></p><div id="doctor-results" class="doctor-directory">${doctors.map(d=>doctorCard(d)).join('')}</div><div class="empty-state" id="doctor-empty" hidden><h2>${T('ไม่พบแพทย์ที่ตรงกับคำค้น','No doctors match your search.')}</h2><button class="primary-button blue-button" data-reset-doctors>${T('แสดงแพทย์ทั้งหมด','Show all doctors')} →</button></div></section>`;
 else if(page==='doctors'&&id){let d=doctors.find(x=>x.id===id)||doctors[0];content=`<section class="doctor-profile"><img src="${d.image}" alt="${locale==='th'?d.name:d.en}"><div><div class="breadcrumb"><a href="#/clinic">${T('หน้าแรก','Home')}</a> › <a href="#/clinic/doctors">${T('แพทย์','Doctors')}</a></div><span class="kicker">${locale==='th'?d.specialty:d.enSpecialty}</span><h1>${locale==='th'?d.name:d.en}</h1><p>${d.degree}</p><p>${doctorStory(d.id,locale)}</p><a class="primary-button blue-button" href="#/clinic/appointment?doctor=${d.id}">${T('นัดหมายแพทย์ท่านนี้','Book this doctor')}</a></div></section><section class="editorial-content profile-details"><h2>${T('ตารางเข้าตรวจ','Consultation schedule')}</h2><div class="schedule-row"><b>${locale==='th'?d.days:d.days}</b><span>08:30–12:00 · 13:00–16:30</span><em>${d.room}</em><a href="#/clinic/appointment?doctor=${d.id}">${T('เลือกเวลานัด','Choose a time')} →</a></div><h2>${T('ความเชี่ยวชาญ','Expertise')}</h2><p>${locale==='th'?d.specialty:d.enSpecialty} · ${d.degree}</p></section>`;}
 else if(page==='packages'&&!id)content=`<section class="page-heading clinic-filter-heading"><span class="kicker">HEALTH PROGRAMS</span><h1>${T('แพ็กเกจและโปรโมชั่น','Packages & promotions')}</h1><p>${T('เลือกโปรแกรมสุขภาพที่เหมาะกับคุณ พร้อมดูราคาและเงื่อนไขก่อนนัดหมาย','Explore screening programs, see clear pricing and terms, then book a visit.')}</p>${clinicPackageFilters()}</section><section class="listing-section"><p class="clinic-result-count" id="package-results-count" role="status" aria-live="polite"></p><div id="package-results" class="package-directory">${packages.map(p=>packageCard(p)).join('')}</div></section><section class="clinic-package-compare"><div class="section-lead"><div><span class="kicker">COMPARE PROGRAMS</span><h2>${T('เปรียบเทียบแพ็กเกจ','Compare packages')}</h2><p>${T('ดูศูนย์บริการ ราคา และรายการที่รวม ก่อนเลือกวันนัดหมาย','Compare centers, pricing and included services before booking.')}</p></div></div><div class="clinic-compare-table-wrap"><table class="clinic-compare-table"><thead><tr><th>${T('แพ็กเกจ','Program')}</th><th>${T('ศูนย์บริการ','Center')}</th><th>${T('ราคา','Price')}</th><th>${T('เหมาะสำหรับ','For')}</th><th>${T('รายการที่รวม','Included')}</th><th></th></tr></thead><tbody>${packages.map(p=>'<tr data-package-comparison data-center="'+p.center+'" data-age="'+p.age+'"><th>'+ (locale==='th'?p.name:p.en) +'</th><td data-label="'+T('ศูนย์บริการ','Center')+'">'+ (locale==='th'?centers.find(c=>c.id===p.center)?.name:centers.find(c=>c.id===p.center)?.en) +'</td><td data-label="'+T('ราคา','Price')+'"><strong>฿'+p.price.toLocaleString()+'</strong></td><td data-label="'+T('เหมาะสำหรับ','For')+'">'+ (locale==='th'?p.age:p.enAge) +'</td><td data-label="'+T('รายการที่รวม','Included')+'"><ul>'+ (locale==='th'?p.items:p.enItems).map(item=>'<li>'+item+'</li>').join('') +'</ul></td><td data-label="'+T('นัดหมาย','Appointment')+'"><a class="compare-book" href="#/clinic/appointment?package='+p.id+'">'+T('นัดหมาย','Book')+' →</a></td></tr>').join('')}</tbody></table></div><p class="prototype-note">${T('ราคาและเงื่อนไขเป็นเนื้อหาตัวอย่างสำหรับเดโม กรุณาตรวจสอบกับสถานพยาบาลก่อนเผยแพร่จริง','Demo pricing and terms. Confirm details with the clinic before launch.')}</p><div class="empty-state" id="package-comparison-empty" hidden>${T('ไม่พบแพ็กเกจตามตัวกรอง','No packages match your filters.')}</div></section>`;
 else if(page==='packages'&&id){let p=packages.find(x=>x.id===id)||packages[0],c=centers.find(x=>x.id===p.center);content=`<section class="detail-hero package-detail-hero"><img src="${c.pic}"><div><div class="breadcrumb"><a href="#/clinic">${T('หน้าแรก','Home')}</a> › <a href="#/clinic/packages">${T('แพ็กเกจ','Packages')}</a></div><span class="kicker">${locale==='th'?c.name:c.en}</span><h1>${locale==='th'?p.name:p.en}</h1><p>${T('โปรแกรมสุขภาพ ออกแบบให้เหมาะกับความต้องการและการดูแลเชิงป้องกัน','A preventive wellness program, designed to support your personal health goals.')}</p><strong class="detail-price">฿${p.price.toLocaleString()}</strong><a class="primary-button" href="#/clinic/appointment?package=${p.id}">${T('นัดหมายแพ็กเกจนี้','Book this package')}</a></div></section><section class="editorial-content"><h2>${T('รายละเอียดแพ็กเกจ','What’s included')}</h2><ul class="detail-list">${(locale==='th'?p.items:p.enItems).map(x=>`<li>✓ &nbsp;${x}</li>`).join('')}</ul><h2>${T('เงื่อนไขการใช้บริการ','Terms & conditions')}</h2><p>${locale==='th'?p.terms:p.enTerms}</p></section>`;}
 else if(page==='articles'&&!id)content=`<section class="page-heading"><span class="kicker">HEALTH LIBRARY</span><h1>${T('คลังความรู้สุขภาพ','Health knowledge')}</h1><p>${T('ข้อมูลสุขภาพจากทีมผู้เชี่ยวชาญ เพื่อประกอบการตัดสินใจดูแลตัวเอง','Ideas and information from our specialists to support your health journey.')}</p><div class="filter-pills">${[T('ทั้งหมด','All'),...new Set(articles.map(a=>locale==='th'?a.cat:a.enCat))].map(x=>`<button data-article-category="${x}" class="${clinicFilters.article===x?'selected':''}">${x}</button>`).join('')}</div></section><section class="listing-section"><div class="article-listing">${articles.map(a=>articleCard(a)).join('')}</div></section>`;
 else if(page==='articles'&&id){let a=articles.find(x=>x.id===id)||articles[0];content=`<article class="article-detail"><div class="breadcrumb"><a href="#/clinic">${T('หน้าแรก','Home')}</a> › <a href="#/clinic/articles">${T('คลังความรู้','Health library')}</a> › ${locale==='th'?a.cat:a.enCat}</div><img src="${a.image}" alt=""><span class="kicker">${locale==='th'?a.cat:a.enCat} · LUMA JOURNAL</span><h1>${locale==='th'?a.title:a.enTitle}</h1><p class="article-lead">${locale==='th'?a.lead:a.enLead}</p>${clinicArticleBody(a.id,locale)}<a class="primary-button blue-button" href="#/clinic/appointment">${T('พูดคุยกับทีมดูแล','Talk with our care team')}</a></article>`;}
 else if(page==='contact')content=contactPage();
 else if(page==='appointment')content=appointmentPage();
 else content=clinicHome();
 return `${header('clinic',page)}<main class="clinic-site">${content}</main>${footer('clinic')}`
}
function doctorCard(d){return `<article class="doctor-card" data-doctor-id="${d.id}"><a href="#/clinic/doctors/${d.id}"><img src="${d.image}" alt=""><small>${locale==='th'?d.specialty:d.enSpecialty}</small><h3>${locale==='th'?d.name:d.en}</h3><span>${T('ตารางตรวจ','Clinic days')}: ${d.days}</span><b>${T('ดูประวัติแพทย์','Doctor profile')}</b></a></article>`}
function packageCard(p){let c=centers.find(x=>x.id===p.center);return `<article class="package-card" data-center="${p.center}" data-age="${p.age}"><img src="${c.pic}" alt=""><div class="package-card-body"><small>${locale==='th'?c.name:c.en} · ${locale==='th'?p.age:p.enAge}</small><h2>${locale==='th'?p.name:p.en}</h2><p>${(locale==='th'?p.items:p.enItems).slice(0,2).join(' · ')}</p><div><strong>฿${p.price.toLocaleString()}</strong><span>${T('เงื่อนไขชัดเจน','Terms available')}</span></div><a href="#/clinic/packages/${p.id}">${T('ดูรายละเอียดแพ็กเกจ','Package details')} →</a></div></article>`}
function articleCard(a){return `<a class="article-tile" data-article-tile="${locale==='th'?a.cat:a.enCat}" href="#/clinic/articles/${a.id}"><img src="${a.image}" alt=""><div><small>${locale==='th'?a.cat:a.enCat}</small><h2>${locale==='th'?a.title:a.enTitle}</h2><p>${locale==='th'?a.lead:a.enLead}</p><span>${T('อ่านบทความ','Read article')}</span></div></a>`}
function mockSocialLinks(){return ['Instagram','Facebook','LINE'].map(platform=>`<button type="button" class="mock-social-link" data-social-preview="${platform}">${platform}</button>`).join('')}
function contactPage(){return `<section class="page-heading"><span class="kicker">CONTACT & LOCATIONS</span><h1>${T('ติดต่อและเดินทางมาหาเรา','Contact & locations')}</h1><p>${T('เราพร้อมช่วยตอบคำถามและแนะนำสาขาที่สะดวกสำหรับคุณ','Our team is ready to answer questions and help you find us.')}</p></section><section class="contact-grid"><div class="branch-cards">${[['Luma Wellness Clinic · Central','88 ถนนวิทยุ แขวงลุมพินี กรุงเทพฯ 10330','08:00–20:00','13.741, 100.546'],['Luma Wellness Clinic · Riverside','Riverwalk Medical Tower, เจริญนคร กรุงเทพฯ 10600','08:00–18:00','13.704, 100.503']].map(b=>`<article><span class="kicker">BANGKOK · THAILAND</span><h2>${b[0]}</h2><p>${b[1]}</p><small>ทุกวัน · ${b[2]}</small><a target="_blank" rel="noreferrer" href="https://maps.google.com/?q=${encodeURIComponent(b[3])}">${T('ขอเส้นทาง Google Maps','Get directions')}</a></article>`).join('')}<a class="direct-contact" href="tel:+6625550188">☎ &nbsp;02 555 0188 </a><a class="direct-contact" href="mailto:hello@lumawellness.example">hello@lumawellness.example</a><div class="social-row">${mockSocialLinks()}</div><small class="mock-contact-note">${T('ข้อมูลติดต่อตัวอย่างสำหรับเดโม','Demo contact information')}</small></div><div class="map-panel"><iframe title="Luma clinic location" src="https://www.openstreetmap.org/export/embed.html?bbox=100.48%2C13.69%2C100.57%2C13.78&amp;layer=mapnik&amp;marker=13.741%2C100.546" loading="lazy"></iframe></div><form id="contact-form" class="simple-form" data-form="contact"><span class="kicker">SEND US A MESSAGE</span><h2>${T('ฝากข้อความถึงเรา','Send us a message')}</h2><label>${T('ชื่อ','Name')}<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>${T('ข้อความ','Message')}<textarea name="message" required rows="4"></textarea></label><button class="primary-button blue-button">${T('ส่งข้อความ','Send message')} →</button><p class="form-message"></p></form></section>`}
function appointmentPage(){const q=new URLSearchParams(location.hash.split('?')[1]||'');return `<section class="booking-layout"><div class="booking-intro"><span class="kicker">LUMA WELLNESS CLINIC · APPOINTMENT</span><h1>${T('นัดหมายรับคำปรึกษา','Book an appointment')}</h1><p>${T('กรอกข้อมูลที่สะดวก ทีมดูแลผู้ป่วยจะติดต่อกลับเพื่อยืนยันนัดหมาย','Tell us your preferences. Our care team will contact you to confirm your visit.')}</p><div class="booking-help"><b>☎ &nbsp;02 555 0188</b><span>${T('เปิดทุกวัน 08:00–20:00 น.','Open daily 08:00–20:00')}</span><button type="button" class="clinic-line-cta" data-social-preview="LINE OA">LINE OA · ${T('ตัวอย่าง','Demo')}</button></div><img src="${photos.clinic}" alt="Luma Wellness Clinic"></div><form class="simple-form appointment-form" data-form="appointment"><div class="form-steps"><b>01</b> ${T('ข้อมูลผู้รับบริการ','Your details')} <i>02</i> ${T('วันและเวลาที่สะดวก','Preferred time')}</div><label>${T('ชื่อและนามสกุล','Full name')}<input name="name" required></label><div class="form-two"><label>${T('เบอร์โทรศัพท์','Phone')}<input name="phone" type="tel" required></label><label>Email<input name="email" type="email" required></label></div><label>${T('ศูนย์บริการที่สนใจ','Select a medical center')}<select name="center" required><option value="">${T('เลือกศูนย์บริการ','Choose a center')}</option>${centers.map(c=>`<option value="${c.id}" ${q.get('center')===c.id?'selected':''}>${locale==='th'?c.name:c.en}</option>`).join('')}</select></label><label>${T('แพทย์ที่ต้องการ (ถ้ามี)','Preferred doctor (optional)')}<select name="doctor"><option value="">${T('ไม่มีแพทย์ที่ต้องการ','No preference')}</option>${doctors.map(d=>`<option value="${d.id}" ${q.get('doctor')===d.id?'selected':''}>${locale==='th'?d.name:d.en}</option>`).join('')}</select></label><label>${T('วันที่สะดวก','Preferred date')}<input type="date" name="date" min="${new Date().toISOString().slice(0,10)}" required></label><label>${T('ช่วงเวลาที่สะดวก','Preferred time')}<select name="time" required><option value="">${T('เลือกช่วงเวลา','Choose a time')}</option><option>08:30–12:00</option><option>13:00–16:30</option><option>16:30–19:00</option></select></label><label class="consent"><input type="checkbox" required> ${T('ยินยอมให้ติดต่อกลับเพื่อยืนยันนัดหมาย','I agree to be contacted to confirm my appointment request.')}</label><button class="primary-button blue-button">${T('ส่งคำขอนัดหมาย','Request appointment')} →</button><p class="form-message" role="status"></p></form></section>`}

function ecoHome(){return `<section class="eco-cover"><video class="eco-hero-video" autoplay muted loop playsinline preload="metadata" poster="https://assets.mixkit.co/videos/43733/43733-thumb-720-0.jpg" aria-hidden="true" tabindex="-1"><source src="https://assets.mixkit.co/videos/43733/43733-720.mp4" type="video/mp4"></video><img class="eco-hero-poster" src="https://assets.mixkit.co/videos/43733/43733-thumb-720-0.jpg" alt="กลุ่มเพื่อนร่วมกิจกรรมโยคะและสมาธิ"><div class="eco-cover-overlay"></div><div class="eco-cover-copy"><span class="kicker light-kicker">GOODKIND · A CONNECTED ECOSYSTEM</span><h1>${T('ผสานสุขภาพและความงาม\nให้เป็นส่วนหนึ่งของทุกวัน','Integrating health, wellness and beauty seamlessly into everyday life.')}</h1><a href="#/eco/story" class="eco-white-button">${T('รู้จักเราเพิ่มเติม','Discover our vision')}</a></div><div class="eco-cover-caption"><span>FEEL WELL, EVERY DAY</span><div class="hero-video-controls"><span>SCROLL TO EXPLORE ↓</span><button class="hero-video-toggle" data-video-toggle type="button" hidden>${T('Ⅱ หยุดวิดีโอ','Ⅱ Pause video')}</button></div></div></section>${ecoExplorer(T)}<section class="eco-mission"><span class="kicker">OUR VISION</span><h2>${T('สุขภาวะที่ดี ควรเข้าถึงง่าย\nและอยู่ใกล้ตัวเรา','Everyday wellness should feel within reach.')}</h2><p>${T('เราสร้าง ecosystem ที่เชื่อมโยงผลิตภัณฑ์ บริการ และพันธมิตร เพื่อเติมสุขภาพ ความงาม และคุณภาพชีวิตที่ดีในทุกวัน','We connect products, services and partners to make wellbeing, beauty and better living part of everyday life.')}</p><a href="#/eco/story">${T('เรื่องราวและพันธกิจ','Our story & values')}</a></section><section class="ecosystem-matrix"><div class="section-lead"><div><span class="kicker">ONE CONNECTED ECOSYSTEM</span><h2>${T('พื้นที่สำหรับเรื่องดี ๆ','A connected world of good things')}</h2></div><p>${T('เลือกค้นพบสินค้า บริการ และประสบการณ์ที่เหมาะกับชีวิตประจำวัน','Discover products, services and experiences for your everyday.')}</p></div><div class="eco-matrix-grid"><a href="#/eco/portfolio"><img src="${photos.store}" alt="Wellness products"><span>01 / PRODUCTS</span><h3>${T('สินค้าคัดสรร','Thoughtful products')}</h3></a><a href="#/eco/stores"><img src="${photos.family}" alt="Wellness community"><span>02 / RETAIL & SERVICES</span><h3>${T('บริการใกล้บ้าน','Welcoming places')}</h3></a><a href="#/eco/partners"><img src="${photos.journal}" alt="Wellness activities"><span>03 / PARTNERS</span><h3>${T('พาร์ตเนอร์ของเรา','Our partners')}</h3></a></div></section>${ecoHighlights(T,photos)}<section class="eco-featured"><div><span class="kicker">OUR RETAIL EXPERIENCE</span><h2>${T('ค้นพบสิ่งดี ๆ ได้ใกล้กว่าที่คิด','Wellness, right around the corner.')}</h2><p>${T('พื้นที่สุขภาพและความงามที่เชื่อมเข้ากับชีวิตประจำวัน ทั้งสินค้าให้เลือกสรร คำแนะนำ และกิจกรรมที่ชวนให้รู้สึกดี','A neighborhood destination for thoughtful products, friendly advice and wellbeing experiences.')}</p><a href="#/eco/stores" class="outline-link">${T('ค้นหาสาขาใกล้คุณ','Find a location')}</a></div><img src="${photos.family}" alt="Wellness experience"></section><section class="eco-news"><div class="section-lead"><div><span class="kicker">NEWS · JOURNAL · COMMUNITY</span><h2>${T('เรื่องราวและกิจกรรมล่าสุด','Latest stories and events')}</h2></div><a href="#/eco/journal" class="outline-link">${T('ดูทั้งหมด','View all')}</a></div><div class="eco-news-grid">${ecoStories().slice(0,3).map(s=>storyCard(s,'eco')).join('')}</div></section><section class="eco-partner-cta"><img src="${photos.nature}" alt="Nature"><div><span class="kicker light-kicker">GROW WITH US</span><h2>${T('มาร่วมเป็นส่วนหนึ่งของ ecosystem','Let’s build better everyday wellness together.')}</h2><p>${T('ชวนแบรนด์และพันธมิตรที่มีแนวคิดเดียวกันมาร่วมเดินทางกับเรา','We welcome brands and partners who share our vision.')}</p><a href="#/eco/partners" class="eco-white-button">${T('โอกาสสำหรับพาร์ตเนอร์','Explore partnerships')}</a></div></section>`}
function ecoStories(){return[{id:'small-rituals',cat:T('WELLNESS JOURNAL','WELLNESS JOURNAL'),title:T('กิจวัตรเล็ก ๆ ที่ช่วยเติมพลังให้วัน','Small rituals to bring more care into your day'),image:photos.journal},{id:'meet-community',cat:T('OUR COMMUNITY','OUR COMMUNITY'),title:T('พบผู้คนเบื้องหลัง Goodkind','Meet the people behind Goodkind'),image:photos.family},{id:'mindful-morning',cat:T('UPCOMING EVENT','UPCOMING EVENT'),title:T('เช้าวันอาทิตย์ที่ได้ขยับกายและพักใจ','A slower Sunday: movement & mindfulness'),image:photos.wellness}]}
function ecoPage(page,id){let content='';
 if(page==='home')content=ecoHome();
 else if(page==='story')content=`<section class="eco-inner-hero"><img src="${photos.family}"><div><span class="kicker light-kicker">OUR BRAND STORY & VISION</span><h1>${T('เติมสุขภาวะที่ดี ให้เป็นเรื่องใกล้ตัว','Making everyday wellbeing more accessible.')}</h1><p>${T('เราเชื่อว่าการดูแลตัวเองควรเข้ากับชีวิตจริงได้อย่างลงตัว','We believe caring for yourself should fit naturally into everyday life.')}</p></div></section><section class="eco-story-block"><span class="kicker">OUR HERITAGE & VALUES</span><h2>${T('การเดินทางที่เริ่มจากความใส่ใจ','A journey rooted in care')}</h2><p>${T('Goodkind Collective เชื่อมโยงแบรนด์สุขภาพและความงามที่คัดสรร พื้นที่บริการที่ต้อนรับ และผู้คนที่อยากใช้ชีวิตได้ดีขึ้นในทุกวัน','Goodkind brings together considered health and beauty brands, welcoming service spaces and people who want to feel better every day.')}</p><div class="eco-value-grid">${[[T('เข้าถึงง่าย','Accessible'),'01'],[T('ใส่ใจอย่างยั่งยืน','Sustainable'),'02'],[T('เติบโตด้วยนวัตกรรม','Innovative'),'03']].map(x=>`<article><i>${x[1]}</i><b>${x[0]}</b><span></span></article>`).join('')}</div></section><section class="sustainability-panel"><img src="${photos.nature}"><div><span class="kicker">OUR COMMITMENT</span><h2>${T('สุขภาวะที่ดี ต้องเติบโตไปพร้อมกับโลก','Better wellbeing, with a lighter footprint.')}</h2><p>${T('เราเลือกทำงานกับแบรนด์และพันธมิตรที่ใส่ใจแหล่งที่มา การใช้ทรัพยากร และชุมชนที่เติบโตไปด้วยกัน','We look for partners who care about sourcing, resources and the communities we grow alongside.')}</p></div></section>`;
 else if(page==='portfolio')content=`<section class="page-heading eco-page-heading"><span class="kicker">OUR PORTFOLIO</span><h1>${T('สินค้า บริการ และโซลูชัน','Products, services & solutions')}</h1><p>${T('แบรนด์สุขภาพและความงามที่เลือกสรร พร้อมบริการและประสบการณ์ที่เชื่อมถึงกัน','A considered portfolio of wellness brands, services and connected experiences.')}</p><div class="filter-pills">${[T('ทั้งหมด','All'),'PRODUCTS','RETAIL','SERVICES'].map(x=>`<button data-eco-filter="${x}">${x}</button>`).join('')}</div></section><section class="listing-section eco-portfolio-list">${[['PRODUCTS',T('แบรนด์สินค้าคัดสรร','Thoughtful product brands'),photos.store],['RETAIL',T('พื้นที่ค้าปลีกและบริการ','Retail & service experiences'),photos.family],['SERVICES',T('โซลูชันสุขภาพสำหรับองค์กร','Corporate health solutions'),photos.team]].map((x,i)=>`<article data-eco-cat="${x[0]}" class="eco-portfolio-row"><img src="${x[2]}"><div><span class="kicker">${x[0]} / GOODKIND COLLECTIVE</span><h2>${x[1]}</h2><p>${[T('Nourish Lab สำหรับกิจวัตรประจำวัน · Goodkind Botanics สำหรับการดูแลผิว · Slow Sunday สำหรับช่วงเวลาพักผ่อน','Nourish Lab for daily rituals, Goodkind Botanics for body care and Slow Sunday for moments of rest.'),T('Goodkind Corner เน้นเลือกซื้อสินค้าและขอคำแนะนำ ส่วน Goodkind Studio เป็นพื้นที่กิจกรรม เวิร์กช็อป และพบปะชุมชน','Goodkind Corner pairs shopping with product guidance. Goodkind Studio hosts workshops, activities and community gatherings.'),T('วางแผนชุดของขวัญองค์กร กิจกรรมสุขภาวะ และเวิร์กช็อปตามขนาดทีม พร้อมประสานแบรนด์และพื้นที่ให้เหมาะกับโครงการ','Plan corporate gift collections, wellness activities and workshops for your team, with brands and venues coordinated around your brief.')][i]}</p><a href="${i===0?'#/shop/products':i===1?'#/eco/stores':'#/eco/partners'}">${T('ค้นพบเพิ่มเติม','Discover more')}</a></div></article>`).join('')}</section>`;
 else if(page==='stores')content=storeLocatorPage();
 else if(page==='partners')content=`<section class="eco-inner-hero partner-hero"><img src="${photos.nature}"><div><span class="kicker light-kicker">BUSINESS PARTNERSHIP · B2B</span><h1>${T('เติบโตไปด้วยกัน','Let’s grow better, together.')}</h1><p>${T('ร่วมเป็นพาร์ตเนอร์ค้าปลีก ขายส่ง แฟรนไชส์ หรือโซลูชันสุขภาพองค์กร','Explore retail, wholesale, franchise and corporate wellness partnerships.')}</p></div></section><section class="partner-content"><div><span class="kicker">PARTNERSHIP OPPORTUNITIES</span><h2>${T('สร้างโอกาสทางธุรกิจที่เชื่อมโยงผู้คนกับสุขภาวะ','Connect people with better everyday wellbeing.')}</h2><div class="partner-options">${[T('ค้าปลีกและจัดจำหน่าย','Retail & distribution'),T('ขายส่งและจัดซื้อองค์กร','Wholesale & corporate'),T('แฟรนไชส์และร่วมลงทุน','Franchise & joint venture'),T('โซลูชันสุขภาพองค์กร','Corporate wellness')].map(x=>`<div>✳ <span>${x}</span></div>`).join('')}</div><div class="eco-partner-steps"><h3>${T('เริ่มต้นความร่วมมือ','Start a conversation')}</h3><ol><li>${T('เลือกประเภทความร่วมมือที่สนใจ','Choose your partnership area')}</li><li>${T('แนะนำบริษัท สินค้า หรือโครงการของคุณ','Introduce your company, products or project')}</li><li>${T('รับหน้าสรุปการส่งข้อเสนอจำลอง','View the demo enquiry confirmation')}</li></ol></div></div><form class="simple-form" data-form="partner"><p class="prototype-note">${T('แบบฟอร์มตัวอย่างสำหรับเดโม · ยังไม่มีการส่งให้ทีมงานหรือบันทึกข้อมูลจริง','Demo enquiry form · no data is stored or sent to a real team.')}</p><h2>${T('พูดคุยกับทีมพาร์ตเนอร์','Talk with our partnerships team')}</h2><label>${T('ชื่อ','Name')}<input name="name" required></label><label>${T('อีเมลธุรกิจ','Business email')}<input type="email" name="email" required></label><label>${T('บริษัท / แบรนด์','Company / brand')}<input name="company" required autocomplete="organization"></label><label>${T('เบอร์โทรติดต่อ','Contact phone')}<input name="phone" type="tel" required></label><label>${T('เว็บไซต์ / ลิงก์แนะนำสินค้า (ถ้ามี)','Website / product link (optional)')}<input name="website" type="url" placeholder="https://"></label><label>${T('สนใจร่วมงานด้านใด','Partnership area')}<select name="interest" required><option value="">${T('เลือกหัวข้อ','Choose an area')}</option>${[['supplier',T('เสนอสินค้า / แบรนด์','Introduce products / brands')],['retail',T('ค้าปลีกและจัดจำหน่าย','Retail & distribution')],['wholesale',T('ขายส่งและจัดซื้อองค์กร','Wholesale & corporate')],['franchise',T('แฟรนไชส์และร่วมลงทุน','Franchise / joint venture')],['corporate',T('โซลูชันสุขภาพองค์กร','Corporate wellness')]].map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>${T('เล่าเกี่ยวกับโอกาสที่สนใจ','Tell us about your opportunity')}<textarea name="message" rows="4" required></textarea></label><label class="consent"><input type="checkbox" name="consent" required> ${T('ยินยอมให้ติดต่อกลับเกี่ยวกับข้อเสนอทางธุรกิจนี้','I agree to be contacted about this business enquiry.')}</label><button class="eco-submit">${T('ส่งข้อเสนอ / คำถาม','Send proposal / enquiry')}</button><p class="form-message"></p></form></section>`;
 else if(page==='journal'&&!id)content=`<section class="page-heading"><span class="kicker">WELLNESS JOURNAL & COMMUNITY</span><h1>${T('แรงบันดาลใจและกิจกรรมดี ๆ','Ideas for a better everyday')}</h1><p>${T('เรื่องราว ไลฟ์สไตล์ และกิจกรรมที่ชวนให้ชุมชนสุขภาวะเติบโต','Lifestyle stories and community experiences for everyday wellness.')}</p></section><section class="eco-story-grid">${ecoStories().map(s=>storyCard(s,'eco')).join('')}</section><section class="upcoming-event"><img src="${photos.wellness}"><div><span class="kicker light-kicker">NEXT COMMUNITY EVENT · 12 OCT 2026</span><h2>${T('Slow Sunday: เคลื่อนไหว พักใจ และจิบชา','Slow Sunday: move, reset & sip tea')}</h2><p>${T('เช้าวันอาทิตย์ที่ชวนคุณมาขยับกายอย่างอ่อนโยน ทำสมาธิสั้น ๆ และพบเพื่อนใหม่','A relaxed Sunday morning with gentle movement, a short guided reset and good company.')}</p><a class="eco-white-button" href="#/eco/events">${T('ดูรายละเอียดกิจกรรม','Event details & registration')}</a></div></section>`;
 else if(page==='journal'&&id){let s=ecoStories().find(x=>x.id===id)||ecoStories()[0];content=`<article class="article-detail eco-article"><div class="breadcrumb"><a href="#/eco">${T('หน้าหลัก','Home')}</a> › <a href="#/eco/journal">${T('บันทึกสุขภาวะ','Journal')}</a></div><img src="${s.image}"><span class="kicker">${s.cat}</span><h1>${s.title}</h1><p class="article-lead">${T('เรื่องราวและแนวคิดเล็ก ๆ ที่ช่วยให้การดูแลตัวเองเป็นส่วนหนึ่งของชีวิตประจำวัน','Simple ideas that make caring for yourself feel like a natural part of the day.')}</p>${journalBody(s.id)}<a class="eco-submit" href="#/eco/events">${T('ดูตารางกิจกรรม','Explore community events')}</a></article>`;}
 else if(page==='events')content=`<section class="page-heading"><span class="kicker">GOODKIND COMMUNITY</span><h1>${T('กิจกรรมและเวิร์กช็อป','Events & workshops')}</h1><p>${T('ลงทะเบียนร่วมกิจกรรมสุขภาวะกับชุมชน Goodkind','Register for a Goodkind community wellness experience.')}</p></section><section class="event-detail"><img src="${photos.wellness}"><div><span class="kicker">12 OCT 2026 · BANGKOK</span><h2>${T('Slow Sunday: เคลื่อนไหว พักใจ และจิบชา','Slow Sunday: move, reset & sip tea')}</h2><p>${T('กิจกรรมเคลื่อนไหวเบา ๆ และผ่อนคลายในบรรยากาศสวน เหมาะสำหรับทุกระดับประสบการณ์','Gentle movement and guided relaxation in the garden. All experience levels are welcome.')}</p><p>08:30–11:00 · Goodkind Studio Riverside · ฿350 ${T('รวมเครื่องดื่ม','includes refreshments')}</p><form class="simple-form compact-form" data-form="event"><label>${T('ชื่อ','Name')}<input required name="name"></label><label>Email<input required name="email" type="email"></label><button class="eco-submit">${T('ลงทะเบียนกิจกรรม','Register for the event')}</button><p class="form-message"></p></form></div></section>`;
 else if(page==='contact')content=`<section class="page-heading"><span class="kicker">CONTACT GOODKIND</span><h1>${T('ติดต่อเรา','Get in touch')}</h1><p>${T('ลูกค้า พาร์ตเนอร์ หรือผู้ที่สนใจสุขภาวะ เรายินดีพูดคุยกับคุณ','Whether you are a customer, partner or wellness enthusiast, we’d love to hear from you.')}</p></section><section class="eco-contact-layout"><div class="contact-details"><h2>Goodkind Health & Wellness</h2><p>304 Vanich Place, Ari · Bangkok 10400</p><a href="mailto:hello@goodkind.example">hello@goodkind.example</a><a href="tel:+6625550199">02 555 0199</a><div class="social-row">${mockSocialLinks()}</div></div><form id="contact-form" class="simple-form" data-form="contact"><h2>${T('ส่งข้อความถึงทีมงาน','Send a message')}</h2><label>${T('ชื่อ','Name')}<input required name="name"></label><label>Email<input type="email" required name="email"></label><label>${T('ข้อความ','Message')}<textarea rows="4" required name="message"></textarea></label><button class="eco-submit">${T('ส่งข้อความ','Send message')}</button><p class="form-message"></p></form></section>`;
 return `${header('eco',page)}<main class="eco-site">${content||ecoHome()}${page==='portfolio'?ecoHighlights(T,photos):''}${['home','journal'].includes(page)?ecoNewsletter(T):''}</main>${footer('eco')}`
}

function storeMapUrl(store){return 'https://www.openstreetmap.org/export/embed.html?bbox='+[store.lon-.025,store.lat-.018,store.lon+.025,store.lat+.018].join('%2C')+'&layer=mapnik&marker='+store.lat+'%2C'+store.lon}
function selectStore(index){selectedStore=index;const store=ecoStores[index];if(!store)return;document.querySelectorAll('[data-store-select]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.storeSelect)===index)));document.querySelectorAll('.store-result').forEach(card=>card.classList.toggle('is-selected',Number(card.dataset.store)===index));const frame=document.querySelector('.store-map iframe');if(frame){frame.src=storeMapUrl(store);frame.title=T('ตำแหน่ง ','Location: ')+(locale==='th'?store.name:store.en)}const caption=document.querySelector('#selected-store-name');if(caption)caption.textContent=locale==='th'?store.name:store.en;const directions=document.querySelector('#selected-store-directions');if(directions)directions.href='https://maps.google.com/?q='+store.lat+','+store.lon}
function storeLocatorPage(){return '<section class="page-heading store-heading"><span class="kicker">STORE LOCATOR & DISTRIBUTION</span><h1>'+T('ค้นหาพื้นที่สุขภาวะใกล้คุณ','Find a place near you')+'</h1><p>'+T('เลือกสาขาเพื่อดูตำแหน่ง บริการ และเส้นทาง','Choose a location to explore services and get directions.')+'</p><div class="store-search"><input id="store-search" aria-label="'+T('ค้นหาสาขา','Search locations')+'" value="'+esc(storeQuery)+'" placeholder="'+T('ค้นหาชื่อสาขาหรือย่าน เช่น อารีย์','Search by location or area, e.g. Ari')+'"><button data-use-location>◎ '+T('ใช้ตำแหน่งของฉัน','Use my location')+'</button></div><p class="eco-store-demo">'+T('ข้อมูลสาขาและเวลาเปิดเป็นตัวอย่างสำหรับเดโม กรุณายืนยันข้อมูลจริงก่อนวางแผนเดินทาง','Locations and hours are illustrative demo data. Confirm actual details before planning a visit.')+'</p></section><section class="store-locator"><div class="store-results"><div class="store-count" id="store-count" role="status"></div>'+ecoStores.map((store,index)=>'<article class="store-result" data-store="'+index+'" data-area="'+esc((store.name+' '+store.en+' '+store.area+' '+store.enArea).toLowerCase())+'" data-lat="'+store.lat+'" data-lon="'+store.lon+'"><span class="kicker">0'+(index+1)+' / GOODKIND LOCATION</span><h2>'+ (locale==='th'?store.name:store.en)+'</h2><p>'+ (locale==='th'?store.area:store.enArea)+'</p><div class="store-hours">◷ '+T(store.hours,store.hours.replace('ทุกวัน','Daily'))+'</div><p>'+T(store.service,['Wellness products · Skin care advice','Workshops · Movement · Retail','Wellness products · Community activities'][index])+'</p><div class="store-card-actions"><button data-store-select="'+index+'" aria-pressed="false">'+T('ดูบนแผนที่','View on map')+'</button><a target="_blank" rel="noreferrer" href="https://maps.google.com/?q='+store.lat+','+store.lon+'">'+T('ขอเส้นทาง','Directions')+'</a></div></article>').join('')+'<p class="empty-state" id="store-empty" hidden>'+T('ไม่พบสาขาที่ตรงกับคำค้น ลองค้นหาด้วยชื่อย่านอื่น','No matching locations. Try another area.')+'<br><button type="button" class="primary-button blue-button" data-reset-stores>'+T('แสดงสาขาทั้งหมด','Show all locations')+'</button></p></div><aside class="store-map"><div class="store-map-heading"><span class="kicker">'+T('ตำแหน่งสาขาที่เลือก','SELECTED LOCATION')+'</span><h2 id="selected-store-name"></h2></div><iframe title="Goodkind location map" src="'+storeMapUrl(ecoStores[selectedStore])+'" loading="lazy"></iframe><div class="store-map-footer"><span>'+T('ตำแหน่งสาขาสำหรับเว็บไซต์ต้นแบบ','Illustrative locations for this prototype')+'</span><a id="selected-store-directions" target="_blank" rel="noreferrer">'+T('เปิดแผนที่เพื่อเดินทาง','Get directions')+'</a></div></aside></section>'}
function journalBody(id){const sections=id==='meet-community'?[['พื้นที่ที่เริ่มจากการรับฟัง','A space built around listening','Goodkind เชื่อว่าพื้นที่สุขภาวะที่ดีเริ่มจากความเข้าใจผู้คน เราจึงออกแบบให้การค้นพบสินค้า การถามคำถาม และการพบคนที่มีความสนใจคล้ายกันเป็นเรื่องง่าย','At Goodkind, we design welcoming spaces where exploring products, asking questions and meeting people with shared interests feels easy.'],['เชื่อมความสนใจให้กลายเป็นชุมชน','Shared interests, stronger connections','ตั้งแต่ผู้ที่เพิ่งเริ่มดูแลตัวเอง ไปจนถึงผู้ที่อยากแบ่งปันกิจวัตรที่ชอบ ทุกคนสามารถร่วมกิจกรรมและแลกเปลี่ยนประสบการณ์ได้ โดยไม่จำเป็นต้องมีพื้นฐานมาก่อน','From people starting a new routine to those sharing a favorite ritual, everyone can join and exchange experiences without previous experience.'],['มาพบกันที่สาขาใกล้คุณ','Meet us in your neighborhood','เลือกดูสาขาและบริการที่ตรงกับความสนใจ หรือเข้าร่วมเวิร์กช็อปเพื่อทำความรู้จักชุมชนในบรรยากาศสบาย ๆ','Explore the services at your nearest location or join a workshop to meet the community in a relaxed setting.']]:[['เริ่มวันด้วยจังหวะที่เหมาะกับตัวเอง','Start at your own pace','เผื่อเวลาเล็กน้อยก่อนเริ่มงาน ลองเปิดม่าน รับแสงธรรมชาติ และเลือกกิจกรรมที่ทำแล้วรู้สึกพร้อมสำหรับวัน โดยไม่ต้องเปลี่ยนกิจวัตรทั้งหมดในครั้งเดียว','Make a little space before work. Open the curtains, enjoy natural light and choose one activity that helps you feel ready, without changing your whole routine at once.'],['สร้างพื้นที่ให้การพักระหว่างวัน','Make room for a pause','วางช่วงพักสั้น ๆ ในตาราง ลุกเปลี่ยนอิริยาบถ หรือออกไปพบพื้นที่สีเขียวใกล้ตัว เลือกช่วงเวลาที่เหมาะกับงานและความสะดวกของคุณ','Plan a short break, change position or visit a nearby green space. Choose a moment that fits your schedule and comfort.'],['เลือกหนึ่งสิ่งที่ทำต่อได้','Choose one thing you can keep doing','จดกิจกรรมที่อยากลองเพียงหนึ่งอย่าง และสังเกตว่ากิจกรรมนั้นเข้ากับชีวิตคุณอย่างไร การดูแลตัวเองสามารถเริ่มจากสิ่งเรียบง่ายที่ทำได้สม่ำเสมอ','Pick just one activity to try and notice how it fits your day. Everyday care can start with a simple habit you enjoy returning to.']];return '<div class="journal-meta">GOODKIND EDITORIAL · '+T('อ่านประมาณ 3 นาที','3 min read')+'</div>'+sections.map(row=>'<section class="journal-section"><h2>'+T(row[0],row[1])+'</h2><p>'+T(row[2],row[3])+'</p></section>').join('')+'<div class="journal-next"><h2>'+T('ค้นพบประสบการณ์ใกล้คุณ','Discover a nearby experience')+'</h2><p>'+T('พบสินค้า บริการ และชุมชนที่สาขา Goodkind','Explore products, services and community at Goodkind.')+'</p><a class="outline-link" href="#/eco/stores">'+T('ค้นหาสาขา','Find a location')+' →</a></div>'}

function storyCard(s,brand='eco'){return `<a class="story-card" href="#/${brand}/${brand==='shop'?'articles':s.id==='mindful-morning'?'events':'journal'}/${s.id==='mindful-morning'&&brand==='eco'?'':s.id}"><img src="${s.image}" alt=""><div><small>${s.cat}</small><h2>${s.title}</h2><span>${T('อ่านต่อ','Read more')}</span></div></a>`}

const catNames=['ทั้งหมด','อาหารเสริม','ดูแลผิว','อุปกรณ์สุขภาพ','การนอน']
function favoritesPage(){
 const saved=products.filter(p=>favorites.has(p.id))
 return `<section class="page-heading"><span class="kicker">YOUR SAVED COLLECTION</span><h1>${T('รายการโปรดของคุณ','Your favorites')}</h1><p>${T('เก็บสินค้าที่ชอบไว้ แล้วเลือกซื้อได้เมื่อพร้อม','Keep the products you love close, and shop when you are ready.')}</p></section><section class="listing-section">${saved.length?`<div class="results-count">${saved.length} ${T('รายการที่บันทึกไว้','saved products')}</div><div class="product-grid">${saved.map(productCard).join('')}</div>`:`<div class="empty-state empty-collection"><span>♡</span><h2>${T('เริ่มสร้างรายการโปรดของคุณ','A little inspiration, saved for later')}</h2><p>${T('แตะหัวใจบนสินค้าที่สนใจเพื่อเก็บไว้ที่นี่','Tap the heart on a product to save it here.')}</p><a class="shop-dark-button" href="#/shop/products">${T('ค้นหาสินค้าที่ชอบ','Explore products')} →</a></div>`}</section>`
}
function catalogPage(){
 const categoryLabel=c=>locale==='th'?c:({'ทั้งหมด':'All','อาหารเสริม':'Supplements','ดูแลผิว':'Body care','อุปกรณ์สุขภาพ':'Health devices','การนอน':'Sleep'})[c]
 return `<section class="catalog-heading"><span class="kicker">NOURISH WELLNESS MARKET</span><h1>${T('ค้นพบสิ่งดี ๆ สำหรับทุกวัน','Good things for your everyday')}</h1><p>${T('สินค้าเพื่อสุขภาพและการดูแลตัวเอง คัดสรรอย่างตั้งใจ','Thoughtfully selected wellness essentials.')}</p></section>${shopConcerns(T)}<section class="catalog-layout"><aside class="catalog-sidebar"><label class="catalog-search">⌕ <input id="product-search" aria-label="${T('ค้นหาสินค้า','Search products')}" value="${esc(shopFilters.query)}" placeholder="${T('ชื่อสินค้า หรือแบรนด์','Product name or brand')}"></label><h3>${T('หมวดหมู่สินค้า','Categories')}</h3>${catNames.map(c=>`<button class="catalog-category ${shopFilters.category===c?'selected':''}" data-shop-category="${c}" aria-pressed="${shopFilters.category===c}">${categoryLabel(c)} <span>${c==='ทั้งหมด'?products.length:products.filter(p=>p.cat===c).length}</span></button>`).join('')}<h3>${T('แบรนด์','Brand')}</h3>${[...new Set(products.map(p=>p.brand))].map(b=>`<label class="brand-filter"><input type="checkbox" value="${b}" ${shopFilters.brands.includes(b)?'checked':''}> ${b}</label>`).join('')}<h3>${T('ราคาสูงสุด','Maximum price')}</h3><div class="price-range"><input type="range" aria-label="${T('ราคาสูงสุด','Maximum price')}" min="0" max="3000" step="10" value="${shopFilters.max}"><output id="price-limit">฿${shopFilters.max.toLocaleString()}</output></div><button class="clear-filters" data-clear-filters>${T('ล้างตัวกรองทั้งหมด','Clear all filters')} ↻</button></aside><div class="catalog-main"><div class="catalog-toolbar"><span id="product-count" class="results-count" role="status"></span><label>${T('เรียงตาม','Sort by')} <select id="sort-products">${[['featured',T('แนะนำ','Featured')],['price',T('ราคาต่ำไปสูง','Price: low to high')],['price-desc',T('ราคาสูงไปต่ำ','Price: high to low')]].map(([value,text])=>`<option value="${value}" ${shopFilters.sort===value?'selected':''}>${text}</option>`).join('')}</select></label></div><div class="product-grid catalog-grid">${products.map(productCard).join('')}</div><div id="product-empty" class="empty-state" hidden><h2>${T('ยังไม่พบสินค้าที่ตรงกับตัวกรอง','No products match your filters')}</h2><p>${T('ลองเปลี่ยนคำค้น หรือเพิ่มช่วงราคา','Try another search or increase your price range.')}</p><button class="shop-dark-button" data-clear-filters>${T('แสดงสินค้าทั้งหมด','Show all products')} →</button></div></div></section>`
}

function initPageUX(r){
 initEcoJourney(r,T)
 const hubLink=document.querySelector('.hub-back-link')
 if(hubLink){const utility=document.createElement('div');utility.className='page-utility';document.querySelector('header').after(utility);utility.append(hubLink);utility.insertAdjacentHTML('beforeend',`<span>${r.brand==='clinic'?'LUMA WELLNESS CLINIC':r.brand==='eco'?'GOODKIND HEALTH & WELLNESS':'NOURISH WELLNESS MARKET'}</span>`)}
 document.querySelectorAll('nav a.active').forEach(a=>a.setAttribute('aria-current','page'))
 document.querySelectorAll('form').forEach(form=>{
  form.querySelectorAll('input[name="name"],input[name="first"],input[name="last"]').forEach(el=>el.autocomplete=el.name==='first'?'given-name':el.name==='last'?'family-name':'name')
  form.querySelectorAll('input[type="email"]').forEach(el=>el.autocomplete='email')
  form.querySelectorAll('input[type="tel"]').forEach(el=>{el.autocomplete='tel';el.inputMode='tel'})
  const msg=form.querySelector('.form-message');if(msg){msg.setAttribute('role','status');msg.setAttribute('aria-live','polite')}
 })
 if(r.brand==='shop'&&r.page==='checkout'){
  const form=document.querySelector('.checkout-form'),panel=document.querySelector('#promptpay-preview')
  const syncPaymentPreview=()=>{if(panel)panel.hidden=form?.elements.payment.value!=='promptpay-demo'}
  form?.addEventListener('change',syncPaymentPreview);syncPaymentPreview()
 }
 if(r.brand==='shop'&&r.page==='products'&&!r.id)filterShop()
 if(r.brand==='eco'&&r.page==='stores'){selectStore(selectedStore);filterStores()}
 if(r.brand==='clinic'&&r.page==='appointment'){
  const form=document.querySelector('.appointment-form'),pkg=packages.find(p=>p.id===r.params.get('package'))
  const doctorId=r.params.get('doctor'),defaultCenter=doctorId==='maya'?'heart':doctorId==='pim'?'brain':doctorId==='narin'?'preventive':''
  if(pkg){form.elements.center.value=pkg.center;form.insertAdjacentHTML('afterbegin',`<div class="booking-selection"><small>${T('แพ็กเกจที่เลือก','Your selected package')}</small><b>${locale==='th'?pkg.name:pkg.en}</b><span>฿${pkg.price.toLocaleString()}</span><input type="hidden" name="package" value="${pkg.id}"></div>`)}else if(defaultCenter)form.elements.center.value=defaultCenter
  const now=new Date();form.elements.date.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`
 }
 if(r.brand==='clinic'&&r.page==='services'&&!r.id){
  const select=document.querySelector('.listing-toolbar select');select.id='center-specialty';select.setAttribute('aria-label',T('กรองศูนย์บริการตามความเชี่ยวชาญ','Filter centers by specialty'))
  document.querySelector('.center-listing').insertAdjacentHTML('afterend',`<p class="empty-state" id="center-empty" hidden>${T('ไม่พบศูนย์บริการ','No centers match your selection.')}</p>`)
 }
 if(r.brand==='eco'&&r.page==='portfolio'){const first=document.querySelector('[data-eco-filter]');first?.classList.add('selected')}
 if(r.brand==='clinic'&&r.page==='packages'&&!r.id)document.querySelector('#package-results').insertAdjacentHTML('afterend',`<div class="empty-state" id="package-empty" hidden><h2>${T('ไม่พบแพ็กเกจตามตัวกรอง','No packages match your filters')}</h2><button class="primary-button blue-button" data-reset-packages>${T('ดูแพ็กเกจทั้งหมด','View all packages')}</button></div>`)
 if(r.brand==='shop'&&r.page==='products'&&r.id){
  const p=products.find(p=>p.id===r.id),gallery=document.querySelector('.gallery-main');gallery.insertAdjacentHTML('beforeend',`<button class="image-zoom" data-image-zoom aria-label="${T('ขยายภาพสินค้า','Enlarge product image')}">⌕</button>`)
  document.querySelector('.gallery-thumbs').remove()
  const buttons=document.querySelector('.product-option>div');buttons.innerHTML=`<button type="button" class="selected" data-product-option="standard">${T('ขนาดมาตรฐาน · 1 ชิ้น','Standard · 1 item')}</button><button type="button" data-product-option="duo">${T('แพ็กคู่ · ลด 10%','Duo pack · save 10%')}</button>`
  const favorite=document.querySelector('.detail-buy .favorite-btn');favorite.innerHTML=favorites.has(r.id)?'♥':'♡';favorite.setAttribute('aria-label',T('บันทึกสินค้าที่ชอบ','Save this product'))
  const qty=cart.find(x=>x.id===r.id)?.qty||0;if(qty)document.querySelector('.detail-buy').insertAdjacentHTML('afterend',`<div class="cart-detail-status">✓ ${T('สินค้านี้อยู่ในตะกร้าแล้ว','Already in your basket')} <b>${qty} ${T('ชิ้น','items')}</b> <a href="#/shop/cart">${T('ดูตะกร้า','View basket')} →</a></div>`)
 }
 document.querySelectorAll('img').forEach(img=>{if(!img.hasAttribute('alt'))img.alt='';img.decoding='async';img.addEventListener('error',()=>{img.classList.add('image-unavailable');img.alt=T('ภาพประกอบ','Illustration')},{once:true})})
}
function closeMenu(){document.querySelectorAll('nav.nav-open').forEach(n=>n.classList.remove('nav-open'));document.querySelectorAll('[data-mobile-menu]').forEach(b=>b.setAttribute('aria-expanded','false'))}
function orderPage(){
 if(!lastOrder)return `<section class="empty-state empty-collection"><h1>${T('ยังไม่มีคำสั่งซื้อ','No order yet')}</h1><p>${T('เลือกสินค้าที่ชอบเพื่อเริ่มคำสั่งซื้อของคุณ','Explore the collection to start your order.')}</p><a class="shop-dark-button" href="#/shop/products">${T('เลือกซื้อสินค้า','Shop products')} →</a></section>`
 const {subtotal,discount,shipping,total}=getOrderTotals(lastOrder.items,products)
 return `<section class="order-success"><div class="success-symbol">✓</div><span class="kicker">ORDER RECEIVED · DEMO</span><h1>${T('ขอบคุณสำหรับคำสั่งซื้อ','Thank you for your order')}</h1><p>${lastOrder.payment==='promptpay-demo'?T('บันทึกคำสั่งซื้อจำลองแล้ว · PromptPay QR ใช้ชำระเงินจริงไม่ได้','Demo order saved · the PromptPay QR preview cannot accept payment'):T('บันทึกคำสั่งซื้อจำลองแล้ว กรุณาโอนเงินตามรายละเอียดด้านล่าง','Your demo order is saved. Use the bank details below to complete this sample transfer.')}</p><b>ORDER #${esc(lastOrder.ref)}</b><div class="order-receipt">${lastOrder.items.map(x=>{const p=products.find(p=>p.id===x.id);return `<div><span>${locale==='th'?p.name:p.en} × ${x.qty}</span><strong>฿${(p.price*x.qty).toLocaleString()}</strong></div>`}).join('')}${discount?`<div><span>${T('ส่วนลดชุดสินค้า','Bundle saving')}</span><strong>−฿${discount.toLocaleString()}</strong></div>`:''}<div><span>${T('ค่าจัดส่ง','Delivery')}</span><strong>${shipping===0?T('ฟรี','FREE'):'฿'+shipping.toLocaleString()}</strong></div><div><span>${T('รวมคำสั่งซื้อ','Order total')}</span><strong>฿${total.toLocaleString()}</strong></div></div>${paymentInstructions(lastOrder.payment,T)}${postPurchaseGuide(lastOrder,products,locale,T)}<a class="shop-dark-button" href="#/shop/products">${T('เลือกซื้อสินค้าต่อ','Continue shopping')} →</a></section>`
}
function openDialog(content,title){
 document.querySelectorAll('dialog.ux-dialog').forEach(el=>el.remove())
 const dialog=document.createElement('dialog');dialog.className='ux-dialog';dialog.setAttribute('aria-label',title)
 dialog.innerHTML=`<button class="dialog-close" aria-label="${T('ปิดหน้าต่าง','Close dialog')}">×</button>${content}`
 dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close())
 dialog.addEventListener('close',()=>dialog.remove())
 dialog.addEventListener('click',e=>{const rect=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom))dialog.close()})
 document.body.append(dialog);dialog.showModal()
}
function showFormSuccess(form,type){
 const data=new FormData(form),ref=`DLG-${Date.now().toString().slice(-7)}`
 const heading=type==='appointment'?T('ได้รับคำขอนัดหมายแล้ว','Appointment request received'):type==='partner'?T('ได้รับข้อมูลความร่วมมือแล้ว','Partnership inquiry received'):type==='event'?T('ลงทะเบียนเรียบร้อยแล้ว','Registration received'):type==='eco-newsletter'?T('สมัครติดตาม Goodkind เรียบร้อย','You are subscribed to the Goodkind Letter'):type==='clinic-newsletter'?T('สมัครรับข่าวสารสุขภาพเรียบร้อย','You are subscribed to Luma Health Notes'):type==='newsletter'?T('สมัครรับข่าวสารเรียบร้อย','You are on the list'):T('ได้รับข้อความของคุณแล้ว','Your message has been received')
 const desc=type==='eco-newsletter'?T('ตัวอย่างขั้นตอนถัดไป: รับบทความและข่าวกิจกรรมทางอีเมลตามความยินยอม','Example next step: receive wellness stories and event updates by email with your consent.'):type==='appointment'?T('ตัวอย่างขั้นตอนถัดไป: ทีมดูแลตรวจสอบวันและเวลา แล้วติดต่อกลับเพื่อยืนยันนัดหมาย','Example next step: a care team reviews the preferred time and contacts the customer to confirm.'):type==='event'?T('ตัวอย่างขั้นตอนถัดไป: ส่งรายละเอียดกิจกรรมและข้อมูลเตรียมตัวให้ผู้ลงทะเบียน','Example next step: share event details and preparation information with the attendee.'):T('ตัวอย่างขั้นตอนถัดไป: ทีมงานทบทวนข้อมูลและตอบกลับตามช่องทางที่ลูกค้าให้ไว้','Example next step: the team reviews the inquiry and responds through the customer’s chosen channel.')
 form.innerHTML=`<section class="form-success" role="status" tabindex="-1"><span class="success-symbol">✓</span><span class="kicker">${type==='eco-newsletter'?'THE GOODKIND LETTER':type==='clinic-newsletter'?'LUMA HEALTH NOTES':type==='newsletter'?'WELCOME TO NOURISH':'REQUEST RECEIVED'}</span><h2>${heading}</h2><p class="prototype-note">${T('การส่งข้อมูลจำลองสำหรับเดโมเท่านั้น ไม่มีการส่งให้ทีมงานจริง','This is a demo confirmation. No information was sent to a real team.')}</p><p>${desc}</p>${data.get('date')?`<div class="request-summary"><b>${esc(data.get('name')||'')}</b><span>${esc(data.get('date'))} · ${esc(data.get('time')||'')}</span></div>`:''}<small>${T('เลขที่อ้างอิง','Reference')} · ${ref}</small><a class="primary-button blue-button" href="#/${route().brand}">${T('กลับหน้าหลัก','Back to home')} →</a></section>`
 form.querySelector('.form-success').focus();toast(heading)
}
